扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: #!/usr/bin/env node
L2: // Regression: untrusted fontFamily must be rejected before it reaches HTML/CSS.
L3: const { spawnSync } = require("child_process");
L4: const fs = require("fs");
L5: const os = require("os");
L6: const path = require("path");
L7: 
L8: const dir = fs.mkdtempSync(path.join(os.tmpdir(), "memo-table-input-"));
L9: const input = path.join(dir, "in.json");
L10: fs.writeFileSync(input, JSON.stringify({
L11:   style: "rounded",
L12:   title: "t",
L13:   headers: ["a", "b"],
L14:   rows: [["1", "2"]],
L15:   fontFamily: "x;}</style><script>alert(1)</script>",
L16: }));
L17: const result = spawnSync(process.execPath, [path.join(__dirname, "render_table.cjs"), input, path.join(dir, "out.png")], { encoding: "utf8" });
L18: fs.rmSync(dir, { recursive: true, force: true });
L19: if (result.status === 0 || !/fontFamily must be/.test(result.stderr || "")) {
L20:   console.error("fontFamily injection was not rejected:", result.status, result.stderr);
L21:   process.exit(1);
L22: }
L23: console.log("fontFamily injection rejected");
